// Hum of the Radix
// status: planned
// requires: engine: no cost sized by the game
// requires: spell cost increase other than mana
// Each artifact spell costs {1} more to cast for each artifact its controller controls.
#[allow(unused_imports)] use cantrip_api::*;
planned_item!("engine-no-cost-sized-by-the-game" => #[allow(unused_variables)] fn more_cost_0(q: &dyn Query, asker: &Asker, targets: &[Target]) -> Cost { (Cost::NONE.and(Cost::mana(ManaCost { generic: 1, x: 0, symbols: [0, 0, 0, 0, 0, 0], hybrid: [None,None,None,None,None,None], twobrid: [0, 0, 0, 0, 0], phyrexian: [0, 0, 0, 0, 0] }))).times(((q.state().battlefield().iter().copied().filter(|&id| (q.chars(id).is(CardType::Artifact) && Some(id).map(|o: ObjectId| q.controller(o)) == Some(q.controller(id)))).collect::<Vec<ObjectId>>()).len() as i64).clamp(0, 255) as u8) });
#[allow(unused_variables)] fn ability_0_0_rule(q: &dyn Query, source: ObjectId, player: PlayerId, costed: Costed, targets: &[Target]) -> CostDelta { let asker = &Asker::new(source, q.controller(source)); let Costed::Spell(spell) = costed else { return CostDelta::NONE; }; if true && q.chars(spell).is(CardType::Artifact) { planned_value!("spell cost increase other than mana", CostDelta::NONE => CostDelta::more_cost(Cost::NONE.and(Cost::mana(ManaCost { generic: 0, x: 0, symbols: [0, 0, 0, 0, 0, 0], hybrid: [None,None,None,None,None,None], twobrid: [0, 0, 0, 0, 0], phyrexian: [0, 0, 0, 0, 0] })).and(planned_value!("engine: no cost sized by the game", Cost::NONE => Cost::reading(more_cost_0))))) } else { CostDelta::NONE } }

